// Parse incoming WhatsApp message (Meta Cloud API format)
const body = $input.item.json.body;

// Handle webhook verification (Meta requires this)
if ($input.item.json.query && $input.item.json.query['hub.mode'] === 'subscribe') {
  return {
    json: {
      isVerification: true,
      challenge: $input.item.json.query['hub.challenge']
    }
  };
}

// Parse the actual message
let messageData = {
  isVerification: false,
  hasMessage: false
};

try {
  const entry = body.entry?.[0];
  const changes = entry?.changes?.[0];
  const value = changes?.value;

  if (value?.messages && value.messages.length > 0) {
    const message = value.messages[0];
    const contact = value.contacts?.[0];

    messageData = {
      isVerification: false,
      hasMessage: true,
      messageId: message.id,
      timestamp: message.timestamp,
      senderPhone: message.from,
      senderName: contact?.profile?.name || 'Unknown',
      messageType: message.type,
      messageContent: message.text?.body || message.caption || '',
      phoneNumberId: value.metadata?.phone_number_id,
      hotelId: entry?.id || 'default', // Hotel ID from webhook config
      rawPayload: body
    };

    // Handle different message types
    if (message.type === 'audio') {
      messageData.audioId = message.audio?.id;
      messageData.needsTranscription = true;
    } else if (message.type === 'image') {
      messageData.imageId = message.image?.id;
      messageData.imageCaption = message.image?.caption || '';
    }
  }
} catch (error) {
  messageData.error = error.message;
}

return { json: messageData };

// Merge message data with hotel configuration
const message = $('Parse WhatsApp Message').item.json;
const hotel = $input.item.json;

return {
  json: {
    // Message data
    messageId: message.messageId,
    senderPhone: message.senderPhone,
    senderName: message.senderName,
    messageContent: message.messageContent,
    messageType: message.messageType,
    timestamp: message.timestamp,

    // Hotel data
    hotelId: hotel.id,
    hotelName: hotel.name,
    confidenceThreshold: parseFloat(hotel.confidence_threshold) || 0.75,
    staffWhatsApp: hotel.staff_whatsapp_number,
    staffPhone: hotel.staff_phone_number,
    whatsappAccessToken: hotel.whatsapp_access_token,
    whatsappPhoneId: hotel.whatsapp_phone_id,
    openaiApiKey: hotel.openai_api_key,
    telegramBotToken: hotel.telegram_bot_token,
    telegramChatId: hotel.telegram_chat_id,

    // Conversation context
    conversationId: hotel.conversation_id,
    previousLanguage: hotel.previous_language,
    currentHandler: hotel.current_handler,
    conversationStatus: hotel.conversation_status,

    // Processing flags
    isNewConversation: !hotel.conversation_id,
    isHandledByHuman: hotel.current_handler === 'human'
  }
};

