// Parse AI analysis and determine next steps
const context = $('Merge Message & Config').item.json;
const aiResponse = $input.item.json.message?.content || $input.item.json;

let analysis;
try {
  analysis = typeof aiResponse === 'string' ? JSON.parse(aiResponse) : aiResponse;
} catch (e) {
  analysis = {
    language: 'en',
    intent: 'unknown',
    confidence: 0.5,
    sentiment: 'neutral',
    is_complex: true,
    wants_human: false,
    entities: {}
  };
}

// Determine if handoff is needed
const confidenceThreshold = context.confidenceThreshold || 0.75;
const needsHandoff = 
  analysis.confidence < confidenceThreshold ||
  analysis.is_complex === true ||
  analysis.wants_human === true ||
  analysis.sentiment === 'angry' ||
  ['complaint', 'refund_request', 'human_request', 'booking_modification', 
   'special_pricing', 'group_reservation', 'unknown'].includes(analysis.intent);

// Determine handoff reason
let handoffReason = null;
if (needsHandoff) {
  if (analysis.wants_human) handoffReason = 'user_requested';
  else if (analysis.sentiment === 'angry') handoffReason = 'angry_customer';
  else if (analysis.confidence < confidenceThreshold) handoffReason = 'low_confidence';
  else if (analysis.is_complex) handoffReason = 'complex_request';
  else handoffReason = 'intent_requires_human';
}

return {
  json: {
    ...context,
    // AI Analysis
    detectedLanguage: analysis.language,
    intent: analysis.intent,
    confidence: analysis.confidence,
    sentiment: analysis.sentiment,
    isComplex: analysis.is_complex,
    wantsHuman: analysis.wants_human,
    entities: analysis.entities,

    // Handoff decision
    needsHandoff: needsHandoff,
    handoffReason: handoffReason,

    // For next nodes
    processedAt: new Date().toISOString()
  }
};

