// Prepare handoff notification message
const context = $input.item.json;

// Generate handoff message based on language
const handoffMessages = {
  sq: 'Faleminderit per mesazhin tuaj. Nje nga stafi yne do t\'ju kontaktoje se shpejti.',
  en: 'Thank you for your message. A member of our team will contact you shortly.',
  it: 'Grazie per il tuo messaggio. Un membro del nostro team ti contatterà a breve.'
};

const reasonMessages = {
  user_requested: {
    sq: 'Klienti kerkoi te flase me stafin',
    en: 'Customer requested to speak with staff',
    it: 'Il cliente ha richiesto di parlare con lo staff'
  },
  angry_customer: {
    sq: 'Klient i pakënaqur - prioritet i lartë',
    en: 'Upset customer - high priority',
    it: 'Cliente insoddisfatto - alta priorità'
  },
  low_confidence: {
    sq: 'AI nuk mund të kuptojë pyetjen',
    en: 'AI could not understand the request',
    it: 'AI non ha compreso la richiesta'
  },
  complex_request: {
    sq: 'Kërkesë komplekse që kërkon staf',
    en: 'Complex request requiring staff',
    it: 'Richiesta complessa che richiede lo staff'
  },
  intent_requires_human: {
    sq: 'Lloji i kërkesës kërkon staf',
    en: 'Request type requires staff attention',
    it: 'Tipo di richiesta richiede attenzione dello staff'
  }
};

const lang = context.detectedLanguage || 'en';
const reason = context.handoffReason || 'complex_request';

return {
  json: {
    ...context,
    customerReplyMessage: handoffMessages[lang] || handoffMessages.en,
    staffNotificationMessage: `
🚨 *New Handoff Required*

🏨 *Hotel:* ${context.hotelName}
📱 *Customer:* ${context.senderPhone}
👤 *Name:* ${context.senderName}
🌐 *Language:* ${lang.toUpperCase()}

💬 *Message:*
"${context.messageContent}"

🎯 *Intent:* ${context.intent}
📊 *Confidence:* ${(context.confidence * 100).toFixed(0)}%
😊 *Sentiment:* ${context.sentiment}

⚠️ *Reason:* ${reasonMessages[reason]?.[lang] || reasonMessages[reason]?.en || reason}

⏰ *Time:* ${new Date().toLocaleString()}
    `.trim()
  }
};

// Get data from previous nodes
const context = $('Analyze Handoff Need').item.json;
const conversationResult = $input.item.json;

return {
  json: {
    ...context,
    dbConversationId: conversationResult.id || context.conversationId
  }
};
